/// Entries in [`LOG_SINE`] and in [`EXPONENT`].
///
/// Source: Ken Shirriff, "Yamaha DX7 reverse-engineering, part III: Inside
/// the log-sine ROM" and "part II: the exponential ROM" (righto.com,
/// December and November 2021): both ROMs take a 10-bit address.
pub const ROM_ENTRIES: usize = 1024;

/// One doubling in the units of [`LOG_SINE`]: its values are logarithms to
/// base two with ten fractional bits.
///
/// Source: Shirriff, part III: "represented as the integer
/// round(y×1024)".
pub const LOG_ONE: u32 = 1024;

